/* ===================== HOME page script ===================== */

// Sticky nav
const nav=document.getElementById('homeNav');
addEventListener('scroll',()=>{nav.classList.toggle('scrolled',scrollY>24)},{passive:true});

// Mobile menu
const burger=document.getElementById('burger'),links=document.getElementById('navLinks');
burger.addEventListener('click',()=>links.classList.toggle('open'));
links.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>links.classList.remove('open')));

// Scroll reveal
const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target)}}),{threshold:.14,rootMargin:'0px 0px -40px'});
document.querySelectorAll('#page-home .reveal').forEach(el=>io.observe(el));

// Active nav link
const secs=[...document.querySelectorAll('#page-home section[id]')];
const navA=[...links.querySelectorAll('a')];
const so=new IntersectionObserver(es=>es.forEach(e=>{
  if(e.isIntersecting){navA.forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#'+e.target.id))}
}),{rootMargin:'-45% 0px -50%'});
secs.forEach(s=>so.observe(s));



