var HOME_LANG = 'en';
function applyHomeLang(lang){
  HOME_LANG = lang;
  document.querySelectorAll('#page-home [data-i18n]').forEach(function(el){
    var entry = HOME_I18N[el.getAttribute('data-i18n')];
    if (entry) el.textContent = entry[lang] || entry.en;
  });
  document.querySelectorAll('#page-home [data-i18n-html]').forEach(function(el){
    var entry = HOME_I18N[el.getAttribute('data-i18n-html')];
    if (entry) el.innerHTML = entry[lang] || entry.en;
  });
  if (document.getElementById('page-home').classList.contains('is-active')){
    document.documentElement.setAttribute('lang', lang);
    document.documentElement.setAttribute('dir', lang === 'ar' ? 'rtl' : 'ltr');
  }
  var label = document.getElementById('langToggleLabel');
  if (label) label.textContent = lang === 'ar' ? 'English' : 'العربية';
  try { localStorage.setItem('site_lang', lang); } catch (e) {}
}
window.__applyHomeLang = typeof applyHomeLang==="function" ? applyHomeLang : function(){};



