const firestoreDb = firebase.firestore();

const DBK='oc_platform_v2';
let DB = seedDB(); // Default sync to avoid undefined before async load

function seedDB(){
  const aid='admin1';
  return {
    users:[
      {id:aid, name:'Khaled Ahmed', email:'admin@coach.com', pass:'admin123', role:'admin', lang:'ar'}
    ],
    plans:[],
    nutri:[],
    records:[],
    messages:[],
    notifications:[],
    feed:[],
  };
}

let isDbLoaded = false;

async function loadDB() { 
  try {
    const docRef = firestoreDb.collection('appData').doc('mainDB');
    const docSnap = await docRef.get();
    
    if (docSnap.exists) {
      DB = docSnap.data();
    } else {
      DB = seedDB();
      await docRef.set(DB);
    }
    isDbLoaded = true;
  } catch(e) {
    console.error("Firebase load error, falling back to local:", e);
    try{DB=JSON.parse(localStorage.getItem(DBK))||seedDB();}catch(ex){DB=seedDB();}
  }
  DB.notifications = DB.notifications||[]; 
  DB.feed = DB.feed||[]; 
  saveDB();
  
  // Refresh UI if user is logged in
  if (typeof APP !== 'undefined' && APP && APP.user && typeof renderApp === 'function') {
    const u = DB.users.find(x => x.id === APP.user.id);
    if (!u) logout(); 
    else { 
      APP.user.name = u.name; 
      APP.user.email = u.email;
      APP.user.role = u.role;
      localStorage.setItem('oc_user', JSON.stringify(APP.user));
      renderApp(); 
    }
  }
}

function saveDB() { 
  localStorage.setItem(DBK, JSON.stringify(DB)); 
  if (isDbLoaded) {
    firestoreDb.collection('appData').doc('mainDB').set(DB)
      .catch(e => console.error("Firebase save error:", e));
  }
}

// Initial async load
loadDB();

