/* ---------- Language ---------- */
function setLang(l){
  APP.lang=l; localStorage.setItem('oc_lang',l);
  try{ window.__applyHomeLang && window.__applyHomeLang(l); }catch(e){}
  const hp=$('#page-home'); if(hp){ hp.lang=l; hp.dir=l==='ar'?'rtl':'ltr'; }
  const rtl=l==='ar';
  document.documentElement.lang=l; document.documentElement.dir=rtl?'rtl':'ltr';
  ['#page-auth','#page-app'].forEach(s=>{const el=$(s); if(el){el.dir=rtl?'rtl':'ltr'; el.lang=l;}});
  $$('.lang-pill button').forEach(b=>b.classList.toggle('on',b.dataset.l===l));
  renderTopBar(); renderAuth(); if(APP.user) renderApp();
}
function renderTopBar(){
  const acts=$('#barActs'); if(!acts) return;
  if(APP.user){
    acts.innerHTML=`<span class="bar-user">${esc(APP.user.name)} · ${APP.user.role==='admin'?L().admin:L().client}</span>
      ${bellHTML()}`;
  }else{
    acts.innerHTML = APP.hash==='#/login' ? '' : `<a class="bar-btn solid" href="#/login" onclick="event.preventDefault();go('#/login')">${L().login}</a>`;
  }
}

/* ---------- Router ---------- */
const PUBLIC=['#/','#/login'];
function go(h){ location.hash=h; }
function route(){
  let h=location.hash||'#/';
  // Plain section anchors (#system, #values, #methodology, #services, #coach, #apply, #top): let the browser scroll natively
  if(!h.startsWith('#/')){
    if(!APP.user){
      APP.hash='#/';
      $('#page-home').style.display='';
      $('#page-auth').hidden=true; $('#page-app').hidden=true;
      return;
    }
    h='#/';
  }
  if(h==='#/register') h='#/login';   // self-registration disabled: accounts are created by the coach
  if(h==='#/logout'){ logout(); return; }
  if(PUBLIC.includes(h) && APP.user){ h = APP.user.role==='admin' ? '#/admin/dashboard' : '#/client/dashboard'; }
  if(!PUBLIC.includes(h) && !APP.user){ h='#/login'; }
  if(h.startsWith('#/admin') && APP.user && APP.user.role!=='admin') h='#/client/dashboard';
  if(h.startsWith('#/client') && APP.user && APP.user.role!=='client') h='#/admin/dashboard';
  APP.hash=h;
  renderTopBar();
  $('#page-home').style.display = h==='#/' ? '' : 'none';
  $('#page-auth').hidden = h!=='#/login';
  $('#page-app').hidden = PUBLIC.includes(h);
  if(h==='#/'){ $('#topLangBar').style.display='flex'; renderTopBar(); }
  if(h==='#/login') renderAuth();
  if(!PUBLIC.includes(h) && APP.user) renderApp();
  window.scrollTo(0,0);
}
window.addEventListener('hashchange',route);

function logout(){ APP.user=null; localStorage.removeItem('oc_user'); go('#/'); route(); toast(L().loggedOut); }

/* ---------- Toast & Modal ---------- */
let toastT;
function toast(m){ const t=$('#apptoast'); t.textContent=m; t.style.display='block'; clearTimeout(toastT); toastT=setTimeout(()=>t.style.display='none',2400); }
function openModal(html){ $('#modal .mbox').innerHTML=html; $('#modal').classList.add('open'); }
function closeModal(){ $('#modal').classList.remove('open'); }
$('#modal') && $('#modal').addEventListener('click',e=>{ if(e.target.id==='modal') closeModal(); });
document.addEventListener('keydown',e=>{ if(e.key==='Escape') closeModal(); });


/* ---------- Notifications & per-client activity feed ---------- */
function notify(userId,type,title,body){
  DB.notifications.push({id:uid(),to:userId,type:type,title:title,body:body,at:new Date().toISOString(),read:false});
  if(DB.notifications.length>300) DB.notifications=DB.notifications.slice(-300);
  saveDB();
  if(APP.user&&APP.user.id===userId) renderTopBar();
}
function feedAdd(cid,icon,text){
  DB.feed.push({id:uid(),cid:cid,icon:icon,text:text,at:new Date().toISOString()});
  if(DB.feed.length>600) DB.feed=DB.feed.slice(-600);
}
function feedFor(cid){ return (DB.feed||[]).filter(f=>f.cid===cid).sort((a,b)=>b.at.localeCompare(a.at)); }
function fmtTime(iso){ const d=new Date(iso); return d.toLocaleDateString(APP.lang==='ar'?'ar-EG':'en-GB',{day:'numeric',month:'short'})+' · '+d.toLocaleTimeString(APP.lang==='ar'?'ar-EG':'en-GB',{hour:'2-digit',minute:'2-digit'}); }
function unreadCount(){ return DB.notifications.filter(n=>n.to===APP.user.id&&!n.read).length; }
function bellHTML(){
  const un=unreadCount();
  return `<button class="notif-btn" onclick="toggleNotifs(event)" aria-label="notifications">${IC.bell}${un?`<span class="nbadge">${un>9?'9+':un}</span>`:''}</button>`;
}
function toggleNotifs(e){
  e.stopPropagation();
  const ex=$('#notifPanel'); if(ex){ ex.remove(); return; }
  const t=L();
  const list=DB.notifications.filter(n=>n.to===APP.user.id).sort((a,b)=>b.at.localeCompare(a.at));
  const unread=list.filter(n=>!n.read), read=list.filter(n=>n.read).slice(0,20);
  const item=n=>`<div class="notif-item ${n.read?'':'unread'}"><div class="nic">${NOTIF_ICONS[n.type]||'🔔'}</div>
    <div style="min-width:0;flex:1"><div class="nt">${esc(n.title)}</div><div class="nb">${esc(n.body)}</div><div class="ntm">${fmtTime(n.at)}</div></div></div>`;
  const div=document.createElement('div'); div.className='notif-panel'; div.id='notifPanel';
  div.innerHTML=`<div class="notif-head"><b>🔔 ${t.notifs}${unread.length?` <span class="badge b-cy">${unread.length} ${t.new_}</span>`:''}</b>
    <div style="display:flex;gap:6px">${unread.length?`<button class="btn btn-g btn-s" onclick="markAllRead()">${t.markAll}</button>`:''}
    <button class="btn btn-g btn-s" onclick="document.getElementById('notifPanel').remove()">✕</button></div></div>
    ${unread.map(item).join('')}
    ${read.length?`<div style="padding:8px;font:700 11px 'Inter';color:#69758a;border-top:1px solid var(--line-d);margin-top:4px">${t.history}</div>${read.map(item).join('')}`:''}
    ${!list.length?`<div class="empty" style="padding:26px">${t.noNotifs}</div>`:''}`;
  document.body.appendChild(div);
  setTimeout(()=>document.addEventListener('click',function h(ev){ if(!div.contains(ev.target)){ div.remove(); document.removeEventListener('click',h);} }),10);
}
function markAllRead(){ DB.notifications.forEach(n=>{ if(n.to===APP.user.id) n.read=true; }); saveDB(); const p=$('#notifPanel'); if(p)p.remove(); renderTopBar(); }
const NOTIF_ICONS={workout:'🏋️',meal:'🥗',message:'💬',plan:'📋',record:'⚖️',join:'👋',client:'➕'};

/* ---------- Searchable combo picker (type to search) ---------- */
function comboHTML(id,ph,val){ return `<div class="combo" id="c_${id}"><input id="i_${id}" placeholder="${ph}" value="${esc(val||'')}" autocomplete="off" onfocus="comboShow('${id}')" oninput="comboInput('${id}')" onkeydown="comboKey(event,'${id}')"></div>`; }
function comboInput(id){ const c=window['CB_'+id]; c.picked=''; comboShow(id); if(c.onpick)c.onpick(''); }
function comboShow(id){
  const c=window['CB_'+id], box=$('#c_'+id), inp=$('#i_'+id);
  const q=inp.value.trim().toLowerCase();
  const items=c.items.filter(it=>!q||(it.d.toLowerCase().includes(q)||(it.s||'').toLowerCase().includes(q))).slice(0,40);
  let lst=box.querySelector('.combo-list');
  if(!lst){ lst=document.createElement('div'); lst.className='combo-list'; box.appendChild(lst); }
  lst.innerHTML=items.length?items.map(it=>`<div class="combo-it${it.v===c.picked?' hl':''}" data-v="${esc(it.v)}" onmousedown="comboPick('${id}',this.dataset.v)">${esc(it.d)}${it.s?`<span class="cm">${esc(it.s)}</span>`:''}</div>`).join(''):`<div class="combo-none">${APP.lang==='ar'?'لا توجد نتائج مطابقة':'No matches'}</div>`;
  c.open=true;
}
function comboHide(id){ const box=$('#c_'+id); if(!box)return; const lst=box.querySelector('.combo-list'); if(lst)lst.remove(); window['CB_'+id].open=false; }
function comboPick(id,v){
  const c=window['CB_'+id]; const it=c.items.find(x=>x.v===v); if(!it)return;
  c.picked=v; $('#i_'+id).value=it.d; comboHide(id);
  if(c.onpick)c.onpick(v);
}
function comboKey(e,id){
  const lst=$('#c_'+id+' .combo-list'); if(!lst)return;
  const its=[...lst.querySelectorAll('.combo-it')]; if(!its.length)return;
  let cur=its.findIndex(x=>x.classList.contains('hl'));
  if(e.key==='ArrowDown'){ e.preventDefault(); cur=Math.min(cur+1,its.length-1); }
  else if(e.key==='ArrowUp'){ e.preventDefault(); cur=Math.max(cur-1,0); }
  else if(e.key==='Enter'){ e.preventDefault(); if(cur<0)cur=0; comboPick(id,its[cur].dataset.v); return; }
  else if(e.key==='Escape'){ comboHide(id); return; }
  else return;
  its.forEach(x=>x.classList.remove('hl')); its[cur].classList.add('hl'); its[cur].scrollIntoView({block:'nearest'});
}
function makeCombo(id,items,onpick){ window['CB_'+id]={items:items,onpick:onpick,picked:''}; }
document.addEventListener('click',e=>{ if(!e.target.closest('.combo')) $$('.combo-list').forEach(l=>l.remove()); });


/* ---------- Charts (canvas, no deps) ---------- */
function lineChart(cv,labels,data,color){
  if(!cv) return; const dpr=window.devicePixelRatio||1;
  const w=cv.clientWidth,h=cv.clientHeight; cv.width=w*dpr; cv.height=h*dpr;
  const x=cv.getContext('2d'); x.scale(dpr,dpr);
  const pad={t:16,r:12,b:26,l:38}, iw=w-pad.l-pad.r, ih=h-pad.t-pad.b;
  const min=Math.min(...data), max=Math.max(...data), rg=(max-min)||1;
  x.strokeStyle='#1E2833'; x.fillStyle='#69758A'; x.font='10px Inter'; x.lineWidth=1;
  for(let i=0;i<=3;i++){ const y=pad.t+ih*i/3; x.beginPath(); x.moveTo(pad.l,y); x.lineTo(w-pad.r,y); x.stroke();
    x.fillText(fmt(max-rg*i/3),2,y+3); }
  const pts=data.map((v,i)=>[pad.l+iw*(data.length===1?.5:i/(data.length-1)), pad.t+ih*(1-(v-min)/rg)]);
  // area
  const g=x.createLinearGradient(0,pad.t,0,h-pad.b); g.addColorStop(0,color+'55'); g.addColorStop(1,color+'00');
  x.beginPath(); x.moveTo(pts[0][0],h-pad.b); pts.forEach(p=>x.lineTo(p[0],p[1])); x.lineTo(pts[pts.length-1][0],h-pad.b); x.closePath(); x.fillStyle=g; x.fill();
  x.beginPath(); pts.forEach((p,i)=>i?x.lineTo(p[0],p[1]):x.moveTo(p[0],p[1])); x.strokeStyle=color; x.lineWidth=2.5; x.lineJoin='round'; x.stroke();
  pts.forEach(p=>{ x.beginPath(); x.arc(p[0],p[1],3.5,0,7); x.fillStyle=color; x.fill(); x.strokeStyle='#07090C'; x.lineWidth=1.5; x.stroke(); });
  x.fillStyle='#8B98A5'; x.textAlign='center';
  labels.forEach((l,i)=>{ if(labels.length>7 && i%2) return; x.fillText(l, pad.l+iw*(labels.length===1?.5:i/(labels.length-1)), h-8); });
  x.textAlign='start';
}
function donutChart(cv,parts){ // parts:[{v,c,l}]
  if(!cv) return; const dpr=window.devicePixelRatio||1;
  const w=cv.clientWidth,h=cv.clientHeight; cv.width=w*dpr; cv.height=h*dpr;
  const x=cv.getContext('2d'); x.scale(dpr,dpr);
  const cx=w/2,cy=h/2,R=Math.min(w,h)/2-8,r=R*.62, tot=parts.reduce((a,p)=>a+p.v,0)||1;
  let a=-Math.PI/2;
  parts.forEach(p=>{ const sw=p.v/tot*Math.PI*2; x.beginPath(); x.arc(cx,cy,R,a+ .02,a+sw-.02); x.arc(cx,cy,r,a+sw-.02,a+.02,true); x.closePath(); x.fillStyle=p.c; x.fill(); a+=sw; });
}
function ringSVG(pct,size){ size=size||54; const R=(size/2)-5, C=2*Math.PI*R;
  return `<div class="ring" style="width:${size}px;height:${size}px"><svg width="${size}" height="${size}"><circle cx="${size/2}" cy="${size/2}" r="${R}" stroke="#1E2833" stroke-width="5" fill="none"/><circle cx="${size/2}" cy="${size/2}" r="${R}" stroke="var(--cyan)" stroke-width="5" fill="none" stroke-linecap="round" stroke-dasharray="${C}" stroke-dashoffset="${C*(1-pct/100)}"/></svg><span class="rv">${fmt(pct)}%</span></div>`; }

/* ---------- Food helpers ---------- */
function foodByName(n){ return FOOD_DB.find(f=>f.n===n); }
function itemMacros(it){ const f=foodByName(it.food); if(!f) return {kcal:0,p:0,c:0,ft:0}; const k=it.g/100;
  return {kcal:f.kcal*k, p:f.p*k, c:f.c*k, ft:f.f*k}; }
function mealMacros(m){ return m.items.reduce((a,it)=>{const x=itemMacros(it); return {kcal:a.kcal+x.kcal,p:a.p+x.p,c:a.c+x.c,ft:a.ft+x.ft};},{kcal:0,p:0,c:0,ft:0}); }
function nutriTotals(np){ return np.meals.reduce((a,m)=>{const x=mealMacros(m); return {kcal:a.kcal+x.kcal,p:a.p+x.p,c:a.c+x.c,ft:a.ft+x.ft};},{kcal:0,p:0,c:0,ft:0}); }

