/* ---------- AUTH ---------- */
let regStep=1, regData={};
function renderAuth(){
  const h=APP.hash, t=L();
  if(h==='#/login'){
    $('#authForm').innerHTML=`
    <div class="auth-card">
      <h1>${t.welcome}</h1><div class="sub">${t.loginSub}</div>
      <div id="authErr"></div>
      <label class="fld"><span>${t.email}</span><input id="liEmail" type="email" dir="ltr" placeholder="name@email.com" autocomplete="email"></label>
      <label class="fld"><span>${t.password}</span><input id="liPass" type="password" dir="ltr" placeholder="••••••••" autocomplete="current-password"></label>
      <button class="btn btn-p btn-block" onclick="doLogin()">${t.login}</button>
      <div class="auth-alt">${t.loginHelp}</div>
    </div>`;
  }else{
    renderRegister();
  }
  $('#authBrand').innerHTML=`
    <img src="${KF_LOGO}" alt="Khaled Fit" class="auth-logo">
    <div class="wm">ONLINE<br><span>COACHING</span></div>
    <div class="tag">${t.brandTag}</div>
    <div class="pts">
      <div class="pt"><i>◆</i>${APP.lang==='en'?'Personalized training & nutrition plans':'خطط تدريب وتغذية مخصصة لك'}</div>
      <div class="pt"><i>◆</i>${APP.lang==='en'?'Real progress tracking with your coach':'متابعة حقيقية للتقدم مع الكوتش'}</div>
      <div class="pt"><i>◆</i>${APP.lang==='en'?'Direct chat and weekly adjustments':'تواصل مباشر وتعديلات أسبوعية'}</div>
    </div>`;
  $('#authForm').dir = APP.lang==='ar'?'rtl':'ltr';
}
async function doLogin(){
  const e=$('#liEmail').value.trim().toLowerCase(), p=$('#liPass').value;
  if(!e||!p){ $('#authErr').innerHTML=`<div class="auth-err">${L().wrong}</div>`; return; }

  // Ensure Firebase data is fully loaded before checking credentials
  if(!isDbLoaded){
    const loginBtn = document.querySelector('#authForm .btn-p');
    if(loginBtn){ loginBtn.disabled=true; loginBtn.textContent='⏳'; }
    try{ await loadDB(); }catch(ex){}
    if(loginBtn){ loginBtn.disabled=false; loginBtn.textContent=L().login; }
  }

  const u=DB.users.find(x=>x.email.toLowerCase()===e && x.pass===p);
  if(!u){ $('#authErr').innerHTML=`<div class="auth-err">${L().wrong}</div>`; return; }
  APP.user={id:u.id,name:u.name,email:u.email,role:u.role};
  localStorage.setItem('oc_user',JSON.stringify(APP.user));
  go(u.role==='admin'?'#/admin/dashboard':'#/client/dashboard'); route();
}
function renderRegister(){
  const t=L(), s=regStep;
  const steps=[t.step1,t.step2,t.step3,t.step4];
  let body='';
  if(s===1) body=`
    <label class="fld"><span>${t.fullName}</span><input id="rgName" value="${esc(regData.name||'')}"></label>
    <label class="fld"><span>${t.phone}</span><input id="rgPhone" dir="ltr" value="${esc(regData.phone||'')}" placeholder="+20..."></label>
    <label class="fld"><span>${t.email}</span><input id="rgEmail" dir="ltr" type="email" value="${esc(regData.email||'')}"></label>
    <label class="fld"><span>${t.password}</span><input id="rgPass" type="password" dir="ltr"></label>
    <label class="fld"><span>${t.pass2}</span><input id="rgPass2" type="password" dir="ltr"></label>`;
  if(s===2) body=`
    <div class="row2">
      <label class="fld"><span>${t.age}</span><input id="rgAge" type="number" inputmode="numeric" value="${regData.age||''}"></label>
      <label class="fld"><span>${t.gender}</span><select id="rgGender"><option value="male" ${regData.gender==='male'?'selected':''}>${t.male}</option><option value="female" ${regData.gender==='female'?'selected':''}>${t.female}</option></select></label>
    </div>
    <div class="row2">
      <label class="fld"><span>${t.height} (cm)</span><input id="rgHeight" type="number" inputmode="numeric" value="${regData.height||''}"></label>
      <label class="fld"><span>${t.weight} (kg)</span><input id="rgWeight" type="number" inputmode="decimal" value="${regData.weight||''}"></label>
    </div>
    <label class="fld"><span>${t.city}</span><input id="rgCity" value="${esc(regData.city||'')}"></label>`;
  if(s===3) body=`
    <label class="fld"><span>${t.conditions}</span><textarea id="rgCond">${esc(regData.conditions||'')}</textarea></label>
    <label class="fld"><span>${t.dietPrefs}</span><textarea id="rgPrefs">${esc(regData.prefs||'')}</textarea></label>
    <label class="fld"><span>${t.trainDays}</span><input id="rgDays" type="number" inputmode="numeric" min="1" max="7" value="${regData.days||3}"></label>`;
  if(s===4){
    const goals=['fatloss','muscle','recomp','strength','endurance','performance','general'];
    body=`<label class="fld"><span>${t.mainGoal}</span></label>
    <div class="chips">${goals.map(g=>`<button class="chip ${regData.goal===g?'on':''}" onclick="regData.goal='${g}';renderRegister()">${t[g]}</button>`).join('')}</div>
    <div id="authErr" style="margin-top:14px"></div>`;
  }
  $('#authForm').innerHTML=`
  <div class="auth-card">
    <h1>${t.joinUs}</h1><div class="sub">${steps[s-1]} · ${s}/4</div>
    <div class="steps-bar">${steps.map((_,i)=>`<i class="${i<s?'on':''}"></i>`).join('')}</div>
    <div id="authErr">${s!==4?'':''}</div>
    ${body}
    <div style="display:flex;gap:10px;margin-top:20px">
      ${s>1?`<button class="btn btn-g" onclick="regStep--;renderRegister()">${t.prev}</button>`:''}
      ${s<4?`<button class="btn btn-p" style="flex:1" onclick="regNext()">${t.next}</button>`
           :`<button class="btn btn-p" style="flex:1" onclick="regSubmit()">${t.submit}</button>`}
    </div>
    <div class="auth-alt">${t.haveAcc} <a href="#/login">${t.login}</a></div>
  </div>`;
}
function regNext(){
  if(regStep===1){
    regData.name=$('#rgName').value.trim(); regData.phone=$('#rgPhone').value.trim(); regData.email=$('#rgEmail').value.trim();
    const p1=$('#rgPass').value,p2=$('#rgPass2').value;
    if(!regData.name||!regData.email||p1.length<6||p1!==p2){ $('#authErr').innerHTML=`<div class="auth-err">${APP.lang==='ar'?'تأكد من البيانات وكلمة المرور (6 أحرف على الأقل ومتطابقة)':'Check your data & password (min 6 chars, must match)'}</div>`; return; }
    if(DB.users.some(u=>u.email.toLowerCase()===regData.email.toLowerCase())){ $('#authErr').innerHTML=`<div class="auth-err">${APP.lang==='ar'?'البريد مسجل بالفعل':'Email already registered'}</div>`; return; }
    regData.pass=p1;
  }
  if(regStep===2){ regData.age=+$('#rgAge').value||''; regData.gender=$('#rgGender').value; regData.height=+$('#rgHeight').value||''; regData.weight=+$('#rgWeight').value||''; regData.city=$('#rgCity').value.trim(); }
  if(regStep===3){ regData.conditions=$('#rgCond').value.trim(); regData.prefs=$('#rgPrefs').value.trim(); regData.days=+$('#rgDays').value||3; }
  regStep++; renderRegister();
}
function regSubmit(){
  if(!regData.goal){ $('#authErr').innerHTML=`<div class="auth-err">${L().mainGoal}…</div>`; return; }
  const u={id:uid(), name:regData.name, email:regData.email, pass:regData.pass, role:'client', goal:regData.goal, status:'pending',
    phone:regData.phone, height:regData.height, gender:regData.gender, city:regData.city, birth:'', joined:today(),
    conditions:regData.conditions, prefs:regData.prefs, age:regData.age, days:regData.days};
  DB.users.push(u);
  if(regData.weight) DB.records.push({id:uid(), clientId:u.id, date:today(), w:regData.weight, bf:''});
  feedAdd(u.id,'👋',(APP.lang==='ar'?'انضم للمنصة':'Joined the platform'));
  notify('admin1','join',L().nJoined,regData.name+' — '+regData.email);
  saveDB(); regStep=1; regData={};
  APP.user={id:u.id,name:u.name,email:u.email,role:'client'}; localStorage.setItem('oc_user',JSON.stringify(APP.user));
  toast(L().regDone); go('#/client/dashboard'); route();
}

