function renderApp(){
  const u=APP.user, t=L(), h=APP.hash;
  const role=u.role, links=navLinks(role);
  const app=$('#page-app'); app.dir=APP.lang==='ar'?'rtl':'ltr';
  let body='';
  if(role==='admin'){
    if(h==='#/admin/dashboard') body=vAdminDash();
    else if(h==='#/admin/clients') body=vClients();
    else if(h.startsWith('#/admin/client/')) body=vClientProfile(h.split('/')[3]);
    else if(h==='#/admin/library') body=vLibrary();
    else if(h==='#/admin/messages') body=vAdminMessages();
    else body=vSettings();
  }else{
    if(h==='#/client/dashboard') body=vClientDash();
    else if(h==='#/client/training') body=vTraining();
    else if(h==='#/client/nutrition') body=vNutrition();
    else if(h==='#/client/progress') body=vProgress();
    else if(h==='#/client/messages') body=vClientMessages();
    else body=vSettings();
  }
  app.innerHTML=`
  <div class="shell">
    <aside class="side" id="side">
      <div class="me"><div class="av">${esc(u.name[0]||'U')}</div><div><div class="nm">${esc(u.name)}</div><div class="rl">${role==='admin'?t.admin:t.client}</div></div></div>
      ${links.map(([href,key,ic])=>`<a class="nl ${h===href?'on':''}" href="${href}">${ic}<span>${t[key]}</span></a>`).join('')}
      <a class="nl out" href="javascript:logout()">${IC.out}<span>${t.logout}</span></a>
    </aside>
    <div class="scrim" id="scrim" onclick="toggleSide(false)"></div>
    <main class="main">${body}</main>
  </div>
  <nav class="bnav">${links.map(([href,key,ic])=>`<a class="${h===href?'on':''}" href="${href}">${ic}<span>${t[key]}</span></a>`).join('')}</nav>`;
  afterRender();
}
function toggleSide(open){ const s=$('#side'),c=$('#scrim'); if(!s) return; const on=open??!s.classList.contains('open'); s.classList.toggle('open',on); c&&c.classList.toggle('open',on); }
function topbar(title,crumb,acts){
  return `<div class="topbar"><div style="display:flex;align-items:center;gap:12px">
    <button class="btn btn-g btn-s" style="display:inline-flex" onclick="toggleSide()" aria-label="menu">${IC.menu}</button>
    <div><h1>${title}</h1><div class="crumb">${crumb||''}</div></div></div>
    <div class="acts">${acts||''}</div></div>`;
}
function afterRender(){
  // hide menu button on desktop
  const mq=window.matchMedia('(min-width:821px)');
  $$('.main .btn[aria-label="menu"]').forEach(b=>b.style.display=mq.matches?'none':'inline-flex');
  const cb=document.getElementById('chatBox'); if(cb) cb.scrollTop=cb.scrollHeight;
  const fn=window.__charts; window.__charts=null; if(fn) fn();
}
function onCharts(fn){ window.__charts=fn; }

/* ---------- ADMIN: Dashboard ---------- */
function vAdminDash(){
  const t=L(), clients=DB.users.filter(u=>u.role==='client');
  const act=clients.filter(c=>c.status==='active').length;
  const nm=clients.filter(c=>(c.joined||'').slice(0,7)===today().slice(0,7)).length;
  const plans=DB.plans.length+DB.nutri.length;
  const months=[],counts=[];
  for(let i=5;i>=0;i--){ const d=new Date(); d.setMonth(d.getMonth()-i); const k=d.toISOString().slice(0,7);
    months.push(d.toLocaleDateString(APP.lang==='ar'?'ar-EG':'en-US',{month:'short'}));
    counts.push(clients.filter(c=>(c.joined||'')<=k+'-31').length); }
  const gk=['fatloss','muscle','recomp','strength','endurance','performance','general'];
  const gc=['#2FD4F5','#08AFCF','#7DD3FC','#34D399','#F59E0B','#A78BFA','#94A3B8'];
  const dist=gk.map((g,i)=>({v:clients.filter(c=>c.goal===g).length,c:gc[i],l:t[g]})).filter(p=>p.v>0);
  const unread=DB.messages.filter(m=>m.to===APP.user.id).length;
  onCharts(()=>{ lineChart($('#chGrowth'),months,counts,'#2FD4F5'); donutChart($('#chGoal'),dist); });
  return topbar(t.dash, `${t.today}: ${new Date().toLocaleDateString(APP.lang==='ar'?'ar-EG':'en-US',{weekday:'long',day:'numeric',month:'long'})}`,
    `<a class="btn btn-p btn-s" href="#/admin/clients" onclick="setTimeout(()=>openClientModal(),50)">＋ ${t.addClient}</a>`)+`
  <div class="grid g4" style="margin-bottom:16px">
    <div class="card stat"><div class="ic">${IC.users}</div><div class="v">${fmt(clients.length)}</div><div class="l">${t.totalClients}</div></div>
    <div class="card stat"><div class="ic">${IC.pulse}</div><div class="v">${fmt(act)}</div><div class="l">${t.activeClients}</div></div>
    <div class="card stat"><div class="ic">${IC.plus}</div><div class="v">${fmt(nm)}</div><div class="l">${t.newMonth}</div></div>
    <div class="card stat"><div class="ic">${IC.check}</div><div class="v">${fmt(plans)}</div><div class="l">${t.plansSet}</div></div>
  </div>
  <div class="grid g2" style="margin-bottom:16px">
    <div class="card"><h3>${t.growth}</h3><canvas class="chart" id="chGrowth"></canvas></div>
    <div class="card"><h3>${t.goalDist}</h3><canvas class="chart" id="chGoal" style="height:180px"></canvas>
      <div class="pill-legend">${dist.map(p=>`<span><i style="background:${p.c}"></i>${p.l} (${p.v})</span>`).join('')}</div></div>
  </div>
  <div class="grid g2">
    <div class="card"><h3>${t.recentClients}</h3>${clientTable(clients.slice().sort((a,b)=>(b.joined||'').localeCompare(a.joined||'')).slice(0,6),false)}</div>
    <div class="card"><h3>${t.activityFeed}</h3>
      ${(()=>{const feed=(DB.feed||[]).slice().sort((a,b)=>b.at.localeCompare(a.at)).slice(0,12);
        return feed.length?feed.map(f=>{const c=DB.users.find(u=>u.id===f.cid);
          return `<div class="notif-item"><div class="nic">${f.icon||'•'}</div><div style="min-width:0;flex:1">
          <div class="nt" style="font-size:12.5px">${c?esc(c.name):'—'}</div>
          <div class="nb">${esc(f.text)}</div><div class="ntm">${fmtTime(f.at)}</div></div></div>`;}).join('')
        :`<div class="empty" style="padding:26px">${t.noActivity}</div>`;})()}
    </div>
  </div>`;
}
function badge(s){ const t=L(); const m={active:'b-ok',pending:'b-wn',inactive:'b-gr'}; return `<span class="badge ${m[s]||'b-gr'}">${t[s]||s}</span>`; }
function clientTable(list,full=true){
  const t=L();
  if(!list.length) return `<div class="empty"><div class="ei">👥</div>${t.noClients}</div>`;
  return `<div class="tbl-wrap"><table class="tbl"><thead><tr>
    <th>${t.fullName}</th><th>${t.status}</th><th>${t.goal}</th><th>${t.weight}</th><th>${t.lastAct}</th><th>${t.actions}</th></tr></thead><tbody>
    ${list.map(c=>{const recs=DB.records.filter(r=>r.clientId===c.id).sort((a,b)=>b.date.localeCompare(a.date));
      const w=recs[0]?recs[0].w+' kg':'—';
      return `<tr>
      <td><b>${esc(c.name)}</b><br><span style="color:#69758A;font-size:11.5px">${esc(c.email)}</span></td>
      <td>${badge(c.status)}</td><td>${t[c.goal]||c.goal||'—'}</td><td>${w}</td>
      <td style="color:#8B98A5;white-space:nowrap;unicode-bidi:isolate">${esc(c.joined||'')}</td>
      <td style="white-space:nowrap">
        <a class="btn btn-g btn-s" href="#/admin/client/${c.id}">${t.view}</a>
        <button class="btn btn-g btn-s" onclick="openClientModal('${c.id}')">${t.edit}</button>
        <button class="btn btn-d btn-s" onclick="delClient('${c.id}')">${t.delete}</button>
      </td></tr>`;}).join('')}</tbody></table></div>`;
}

/* ---------- ADMIN: Clients ---------- */
let clFilter={q:'',st:''};
function vClients(){
  const t=L(), clients=DB.users.filter(u=>u.role==='client');
  let list=clients.filter(c=>!clFilter.st||c.status===clFilter.st)
    .filter(c=>!clFilter.q||(c.name+' '+c.email).toLowerCase().includes(clFilter.q.toLowerCase()));
  return topbar(t.clients,`${clients.length} ${t.clients.toLowerCase()}`,`<button class="btn btn-p btn-s" onclick="openClientModal()">＋ ${t.addClient}</button>`)+`
  <div class="fbar">
    <input id="clSearch" placeholder="${t.search}" value="${esc(clFilter.q)}" oninput="clFilter.q=this.value;renderApp();refocus('clSearch')">
    <select onchange="clFilter.st=this.value;renderApp()">
      <option value="">${t.all}</option>
      ${['active','pending','inactive'].map(s=>`<option value="${s}" ${clFilter.st===s?'selected':''}>${t[s]}</option>`).join('')}
    </select>
  </div>
  ${clientTable(list)}`;
}
function openClientModal(id){
  const t=L(), c=id?DB.users.find(u=>u.id===id):null;
  openModal(`<h3>${c?t.edit:t.addClient}</h3>
  <label class="fld"><span>${t.fullName}</span><input id="mcName" value="${esc(c?.name||'')}"></label>
  <div class="row2">
    <label class="fld"><span>${t.email}</span><input id="mcEmail" dir="ltr" value="${esc(c?.email||'')}"></label>
    <label class="fld"><span>${t.phone}</span><input id="mcPhone" dir="ltr" value="${esc(c?.phone||'')}"></label>
  </div>
  <div class="row2">
    <label class="fld"><span>${t.newPass}${c?' · '+t.passKeep:''}</span><input id="mcPass" dir="ltr" type="text" value="" placeholder="••••••••"></label>
    <label class="fld"><span>${t.gender}</span><select id="mcGender"><option value="male" ${c?.gender!=='female'?'selected':''}>${t.male}</option><option value="female" ${c?.gender==='female'?'selected':''}>${t.female}</option></select></label>
  </div>
  <div class="row3">
    <label class="fld"><span>${t.age}</span><input id="mcAge" type="number" value="${c?.age||''}"></label>
    <label class="fld"><span>${t.height}</span><input id="mcHeight" type="number" value="${c?.height||''}"></label>
    <label class="fld"><span>${t.weight}</span><input id="mcW" type="number" step="0.1" value=""></label>
  </div>
  <div class="row2">
    <label class="fld"><span>${t.goal}</span><select id="mcGoal">${['fatloss','muscle','recomp','strength','endurance','performance','general'].map(g=>`<option value="${g}" ${c?.goal===g?'selected':''}>${t[g]}</option>`).join('')}</select></label>
    <label class="fld"><span>${t.status}</span><select id="mcStatus">${['active','pending','inactive'].map(s=>`<option value="${s}" ${c?.status===s?'selected':''}>${t[s]}</option>`).join('')}</select></label>
  </div>
  <label class="fld"><span>${t.notes}</span><textarea id="mcNotes">${esc(c?.notes||'')}</textarea></label>
  <div style="display:flex;gap:10px;margin-top:8px">
    <button class="btn btn-p" style="flex:1" onclick="saveClient('${id||''}')">${t.save}</button>
    <button class="btn btn-g" onclick="closeModal()">${t.cancel}</button>
  </div>`);
}
function saveClient(id){
  const t=L();
  const pass=$('#mcPass').value.trim();
  const d={name:$('#mcName').value.trim(),email:$('#mcEmail').value.trim(),phone:$('#mcPhone').value.trim(),
    age:+$('#mcAge').value||'',height:+$('#mcHeight').value||'',goal:$('#mcGoal').value,status:$('#mcStatus').value,notes:$('#mcNotes').value.trim(),gender:$('#mcGender').value};
  if(!d.name||!d.email||(!id&&pass.length<6)){ toast(t.fillCreds); return; }
  const clash=DB.users.find(u=>u.email.toLowerCase()===d.email.toLowerCase()&&u.id!==id);
  if(clash){ toast(t.emailTaken); return; }
  const w=+$('#mcW').value;
  if(id){ const u=DB.users.find(u=>u.id===id); Object.assign(u,d); if(pass) u.pass=pass; }
  else{ const nu={id:uid(),...d,pass:pass,role:'client',city:'',birth:'',joined:today(),conditions:'',prefs:''};
    DB.users.push(nu); if(w) DB.records.push({id:uid(),clientId:nu.id,date:today(),w,bf:''});
    feedAdd(nu.id,'👋',(APP.lang==='ar'?'تم إنشاء الحساب بواسطة الكوتش':'Account created by coach'));
    notify('admin1','client',t.nClientAdded,d.name+' — '+d.email); }
  if(id&&w){ DB.records.push({id:uid(),clientId:id,date:today(),w,bf:''}); feedAdd(id,'⚖️',(APP.lang==='ar'?'سجل وزن جديد: ':'New weight record: ')+w+' kg'); }
  saveDB(); closeModal(); toast(t.credsSent); renderApp();
}
function delClient(id){
  if(!confirm(L().deleteSure)) return;
  DB.users=DB.users.filter(u=>u.id!==id); DB.plans=DB.plans.filter(p=>p.clientId!==id);
  DB.nutri=DB.nutri.filter(n=>n.clientId!==id); DB.records=DB.records.filter(r=>r.clientId!==id);
  DB.feed=DB.feed.filter(f=>f.cid!==id);
  saveDB(); go('#/admin/clients'); renderApp();
}

/* ---------- ADMIN: Client Profile (tabs) ---------- */
let profTab=0;
function vClientProfile(cid){
  const t=L(), c=DB.users.find(u=>u.id===cid);
  if(!c) return topbar(t.clients)+`<div class="empty">404</div>`;
  const plan=DB.plans.find(p=>p.clientId===cid), np=DB.nutri.find(n=>n.clientId===cid);
  const recs=DB.records.filter(r=>r.clientId===cid).sort((a,b)=>a.date.localeCompare(b.date));
  const last=recs[recs.length-1], first=recs[0];
  const tabs=[t.overview,t.personal,t.training,t.nutrition,t.progress,t.activityFeed,t.access];
  let body='';
  if(profTab===0){
    body=`<div class="grid g4" style="margin-bottom:16px">
      <div class="card stat"><div class="l">${t.weight}</div><div class="v">${last?last.w:'—'}<small style="font-size:13px;color:#8B98A5"> kg</small></div>
        <div class="d ${first&&last&&last.w<first.w?'up':'dn'}">${first&&last?(last.w-first.w).toFixed(1)+' kg':'—'}</div></div>
      <div class="card stat"><div class="l">${t.bodyFat}</div><div class="v">${last&&last.bf?last.bf+'%':'—'}</div></div>
      <div class="card stat"><div class="l">${t.goal}</div><div class="v" style="font-size:18px">${t[c.goal]||'—'}</div></div>
      <div class="card stat"><div class="l">${t.plan}</div><div class="v" style="font-size:18px">${plan||np?`<span class="badge b-cy">${plan?'🏋️':''}${np?' 🥗':''}</span>`:t.none}</div></div>
    </div>
    <div class="card"><h3>${t.weightLog}</h3><canvas class="chart" id="chW"></canvas></div>`;
    if(recs.length>1) onCharts(()=>lineChart($('#chW'),recs.map(r=>r.date.slice(5)),recs.map(r=>r.w),'#2FD4F5'));
    else body=`<div class="empty">${t.noPlan}</div>`;
  }
  if(profTab===1){
    const row=(k,v)=>`<div class="it" style="display:flex;justify-content:space-between;padding:10px 0;border-top:1px dashed #1c2630"><span style="color:#8B98A5">${k}</span><b style="color:#fff">${TD(v||'—')}</b></div>`;
    body=`<div class="card"><h3>${t.personal}</h3>
      ${row(t.fullName,c.name)}${row(t.email,c.email)}${row(t.phone,c.phone)}${row(t.age,c.age)}${row(t.gender,c.gender?t[c.gender]:'')}${row(t.height,c.height?c.height+' cm':'')}${row(t.city,c.city)}
      <h3 style="margin-top:18px">${t.health}</h3>
      ${row(t.conditions,c.conditions)}${row(t.dietPrefs,c.prefs)}${row(t.notes,c.notes)}
      <button class="btn btn-p btn-s" style="margin-top:16px" onclick="openClientModal('${c.id}')">${t.edit}</button></div>`;
  }
  if(profTab===2){
    body=`<div class="card" style="margin-bottom:14px"><div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px">
      <h3 style="margin:0">${t.buildPlan}</h3>
      <div style="display:flex;gap:8px"><button class="btn btn-g btn-s" onclick="openPlanBuilder('${cid}')">${plan?t.edit:t.add}</button></div></div>
      ${plan?`<div style="margin-top:14px">${plan.days.map((d,i)=>dayCardHTML(d,i,cid,false)).join('')}</div>`:`<div class="empty">${t.noPlan}</div>`}</div>`;
  }
  if(profTab===3){
    body=`<div class="card" style="margin-bottom:14px"><div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px">
      <h3 style="margin:0">${t.nutriPlan}</h3>
      <div style="display:flex;gap:8px"><button class="btn btn-g btn-s" onclick="openNutriBuilder('${cid}')">${np?t.edit:t.add}</button></div></div>
      ${np?nutriPlanHTML(np,cid,false):`<div class="empty">${t.noNutri}</div>`}</div>`;
  }
  if(profTab===4){
    body=`<div class="card"><h3>${t.weightLog}</h3>
      ${recs.length>1?`<canvas class="chart" id="chW"></canvas>`:''}
      <div class="tbl-wrap" style="margin-top:12px"><table class="tbl" style="min-width:0"><thead><tr><th>${t.date}</th><th>${t.weight}</th><th>${t.bodyFat}</th></tr></thead>
      <tbody>${recs.slice().reverse().map(r=>`<tr><td>${r.date}</td><td>${r.w} kg</td><td>${r.bf?r.bf+'%':'—'}</td></tr>`).join('')}</tbody></table></div>
      <button class="btn btn-p btn-s" style="margin-top:14px" onclick="addRecord('${cid}')">＋ ${t.addRecord}</button></div>`;
    if(recs.length>1) onCharts(()=>lineChart($('#chW'),recs.map(r=>r.date.slice(5)),recs.map(r=>r.w),'#2FD4F5'));
  }
  if(profTab===5){
    const feed=feedFor(cid);
    body=`<div class="card"><h3>${t.activityFeed}</h3>
      ${feed.length?feed.map(f=>`<div class="notif-item"><div class="nic">${f.icon||'•'}</div>
        <div style="min-width:0;flex:1"><div class="nb" style="color:#dbe6ee">${esc(f.text)}</div><div class="ntm">${fmtTime(f.at)}</div></div></div>`).join('')
        :`<div class="empty">${t.noActivity}</div>`}</div>`;
  }
  if(profTab===6){
    body=`<div class="card" style="max-width:520px"><h3>${t.access}</h3>
      <label class="fld"><span>${t.email}</span><input id="acEmail" dir="ltr" value="${esc(c.email)}"></label>
      <label class="fld"><span>${t.newPass} · ${t.passKeep}</span><input id="acPass" dir="ltr" type="text" placeholder="••••••••"></label>
      <button class="btn btn-p btn-s" onclick="saveAccess('${c.id}')">${t.save}</button></div>`;
  }
  return topbar(esc(c.name),`<span class="badge b-cy">${t[c.goal]||''}</span> ${badge(c.status)}`)+
    `<div class="tabs">${tabs.map((x,i)=>`<button class="${profTab===i?'on':''}" onclick="profTab=${i};renderApp()">${x}</button>`).join('')}</div>${body}`;
}
function saveAccess(cid){
  const t=L(), c=DB.users.find(u=>u.id===cid);
  const em=$('#acEmail').value.trim(), ps=$('#acPass').value.trim();
  if(!em){ toast('!'); return; }
  const clash=DB.users.find(u=>u.email.toLowerCase()===em.toLowerCase()&&u.id!==cid);
  if(clash){ toast(t.emailTaken); return; }
  c.email=em; if(ps){ if(ps.length<6){ toast(t.fillCreds); return; } c.pass=ps; }
  feedAdd(cid,'🔑',(APP.lang==='ar'?'الكوتش حدث بيانات الدخول':'Coach updated login credentials'));
  saveDB(); toast(t.credsSent); renderApp();
}
function addRecord(cid){
  const t=L();
  openModal(`<h3>${t.addRecord}</h3>
  <div class="row2"><label class="fld"><span>${t.weight} (kg)</span><input id="arW" type="number" step="0.1"></label>
  <label class="fld"><span>${t.bodyFat} (%)</span><input id="arBF" type="number" step="0.1"></label></div>
  <div style="display:flex;gap:10px"><button class="btn btn-p" style="flex:1" onclick="const w=+document.querySelector('#arW').value;if(w){DB.records.push({id:uid(),clientId:'${cid}',date:today(),w,bf:+document.querySelector('#arBF').value||''});feedAdd('${cid}','⚖️',(APP.lang==='ar'?'سجل وزن جديد: ':'New weight record: ')+w+' kg');if(APP.user.role==='client')notify('admin1','record',APP.user.name,L().nWeight+': '+w+' kg');saveDB();closeModal();toast(L().recordAdded);renderApp();}">${t.save}</button>
  <button class="btn btn-g" onclick="closeModal()">${t.cancel}</button></div>`);
}
function dayCardHTML(d,i,cid,clientView){
  const t=L(), dn=d.name?(APP.lang==='ar'?d.name.ar:d.name.en):`${t.day} ${i+1}`;
  const done=(window.__plan&&false);
  return `<div class="wcard" style="margin-bottom:12px">
    <div class="wh"><div><div class="t">${TD(dn)}</div><div class="s">${d.ex.length} ${t.exercises} · ~${d.ex.length*8} ${t.dur}</div></div>
    ${clientView?`<button class="btn ${d._done?'btn-g':'btn-p'} btn-s" onclick="toggleDayDone(${i})">${d._done?'✓ '+t.completed:t.completeWorkout}</button>`:''}</div>
    ${d.ex.map((x,j)=>`<div class="exrow"><div class="no">${j+1}</div>
      <div class="inf"><div class="n">${TD(x.n)}</div><div class="m">${esc(exMeta(x.n))}</div></div>
      <div class="par">${x.s} × ${x.r} · ${x.rest}s</div></div>`).join('')}
  </div>`;
}
function exMeta(n){ const e=EX_DB.find(x=>x.n===n); return e?`${e.m} · ${e.eq}`:''; }

/* ---------- Plan Builder ---------- */
let pb=null;
function openPlanBuilder(cid){
  const t=L(); const cur=DB.plans.find(p=>p.clientId===cid);
  pb={cid, days:cur?JSON.parse(JSON.stringify(cur.days)):[{name:{en:'Day 1',ar:'اليوم 1'},ex:[{n:'',s:3,r:'10',rest:60}]}]};
  renderPlanBuilder();
}
function exLabel(n){ const e=EX_DB.find(x=>x.n===n); if(!e) return n; return APP.lang==='ar'?e.n:(e.e+' — '+e.n); }
function renderPlanBuilder(){
  const t=L();
  openModal(`<h3>${t.buildPlan}</h3>
  <div id="pbDays">${pb.days.map((d,i)=>`
    <div style="border:1px solid var(--line-d);border-radius:14px;padding:12px;margin-bottom:12px">
      <div style="display:flex;gap:8px;margin-bottom:10px">
        <input style="flex:1;background:#0d1319;border:1px solid var(--line-d);border-radius:10px;padding:9px 12px;color:#fff" value="${esc(APP.lang==='ar'?d.name.ar:d.name.en)}" onchange="pb.days[${i}].name.en=this.value;pb.days[${i}].name.ar=this.value">
        <button class="btn btn-d btn-s" onclick="pb.days.splice(${i},1);renderPlanBuilder()">✕</button>
      </div>
      ${d.ex.map((x,j)=>`<div class="row3" style="grid-template-columns:1fr 70px 70px 70px 30px;display:grid;margin-bottom:8px">
        ${comboHTML('ex'+i+'_'+j, t.pickEx, x.n?exLabel(x.n):'')}
        <input type="number" value="${x.s}" onchange="pb.days[${i}].ex[${j}].s=+this.value" placeholder="${t.sets}" style="background:#0d1319;border:1px solid var(--line-d);border-radius:10px;padding:8px;color:#fff">
        <input value="${x.r}" onchange="pb.days[${i}].ex[${j}].r=this.value" placeholder="${t.reps}" style="background:#0d1319;border:1px solid var(--line-d);border-radius:10px;padding:8px;color:#fff">
        <input type="number" value="${x.rest}" onchange="pb.days[${i}].ex[${j}].rest=+this.value" placeholder="${t.rest}" style="background:#0d1319;border:1px solid var(--line-d);border-radius:10px;padding:8px;color:#fff">
        <button class="btn btn-d btn-s" style="padding:6px" onclick="pb.days[${i}].ex.splice(${j},1);renderPlanBuilder()">✕</button>
      </div>`).join('')}
      <button class="btn btn-g btn-s" onclick="pb.days[${i}].ex.push({n:'',s:3,r:'10',rest:60});renderPlanBuilder()">＋ ${t.exercise}</button>
    </div>`).join('')}</div>
  <div style="display:flex;gap:10px;flex-wrap:wrap">
    <button class="btn btn-g" onclick="pb.days.push({name:{en:'Day '+(pb.days.length+1),ar:'اليوم '+(pb.days.length+1)},ex:[{n:'',s:3,r:'10',rest:60}]});renderPlanBuilder()">＋ ${t.addDay}</button>
    <button class="btn btn-p" style="flex:1" onclick="savePlan()">${t.assignPlan}</button>
    <button class="btn btn-g" onclick="closeModal()">${t.cancel}</button>
  </div>`);
  pb.days.forEach((d,i)=>d.ex.forEach((x,j)=>{
    const id='ex'+i+'_'+j;
    makeCombo(id, EX_DB.map(e=>({v:e.n, d:APP.lang==='ar'?e.n:(e.e+' — '+e.n), s:(L()[e.c]||e.c)+' · '+e.m+' · '+e.eq})),
      v=>{ pb.days[i].ex[j].n=v; });
    if(x.n) window['CB_'+id].picked=x.n;
  }));
}
function savePlan(){
  // pull latest typed/picked values from combos (never lose input)
  pb.days.forEach((d,i)=>d.ex.forEach((x,j)=>{
    const c=window['CB_ex'+i+'_'+j];
    if(c){ if(c.picked) x.n=c.picked; }
  }));
  pb.days=pb.days.filter(d=>d.ex.some(x=>x.n));
  pb.days.forEach(d=>d.ex=d.ex.filter(x=>x.n));
  const cur=DB.plans.find(p=>p.clientId===pb.cid);
  if(cur){ cur.days=pb.days; } else DB.plans.push({id:uid(),clientId:pb.cid,createdAt:today(),days:pb.days,completed:[],createdBy:APP.user.id});
  feedAdd(pb.cid,'📋',(APP.lang==='ar'?'الكوتش حدث خطة التدريب':'Coach updated the training plan'));
  notify(pb.cid,'plan',L().nPlanAssigned,L().buildPlan);
  saveDB(); closeModal(); toast(L().planAssigned); renderApp();
}

/* ---------- Nutrition Builder ---------- */
let nb=null;
function openNutriBuilder(cid){
  const cur=DB.nutri.find(n=>n.clientId===cid);
  nb={cid, targets:cur?{...cur.targets}:{kcal:2500,p:150,c:280,f:70},
      meals:cur?JSON.parse(JSON.stringify(cur.meals)):[{id:uid(),name:{en:'Breakfast',ar:'الفطار'},time:'08:00',done:false,items:[{food:'',g:100}]}]};
  renderNutriBuilder();
}
function renderNutriBuilder(){
  const t=L(); const tot={kcal:0,p:0,c:0,ft:0};
  nb.meals.forEach(m=>{const x=m.items.reduce((a,it)=>{const f=FOOD_DB.find(f=>f.n===it.food); if(f){a.kcal+=f.kcal*it.g/100;a.p+=f.p*it.g/100;a.c+=f.c*it.g/100;a.ft+=f.f*it.g/100;} return a;},{kcal:0,p:0,c:0,ft:0}); tot.kcal+=x.kcal;tot.p+=x.p;tot.c+=x.c;tot.ft+=x.ft;});
  const cats=[...new Set(FOOD_DB.map(f=>f.cat))];
  openModal(`<h3>${t.nutriPlan}</h3>
  <div class="card" style="padding:12px;margin-bottom:12px;background:#0d1319">
    <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:8px;margin-bottom:10px">
      <b style="color:#fff;font-size:13px">${t.targets}</b>
      <button class="btn btn-g btn-s" onclick="calcTargets('${nb.cid}')">⚡ ${t.calcTitle}</button>
    </div>
    <div class="row3" style="grid-template-columns:repeat(4,1fr)">
      <label class="fld" style="margin:0"><span>${t.calories}</span><input type="number" value="${nb.targets.kcal}" onchange="nb.targets.kcal=+this.value"></label>
      <label class="fld" style="margin:0"><span>${t.protein}</span><input type="number" value="${nb.targets.p}" onchange="nb.targets.p=+this.value"></label>
      <label class="fld" style="margin:0"><span>${t.carbs}</span><input type="number" value="${nb.targets.c}" onchange="nb.targets.c=+this.value"></label>
      <label class="fld" style="margin:0"><span>${t.fats}</span><input type="number" value="${nb.targets.f}" onchange="nb.targets.f=+this.value"></label>
    </div>
    <div style="color:#8B98A5;font-size:11.5px;margin-top:8px">${t.totals}: ${fmt(tot.kcal)} kcal · ${fmt(tot.p)}P / ${fmt(tot.c)}C / ${fmt(tot.ft)}F</div>
  </div>
  ${nb.meals.map((m,i)=>`
    <div style="border:1px solid var(--line-d);border-radius:14px;padding:12px;margin-bottom:12px">
      <div style="display:flex;gap:8px;margin-bottom:10px">
        <input style="flex:1;background:#0d1319;border:1px solid var(--line-d);border-radius:10px;padding:9px 12px;color:#fff" value="${esc(APP.lang==='ar'?m.name.ar:m.name.en)}" onchange="nb.meals[${i}].name.en=this.value;nb.meals[${i}].name.ar=this.value" placeholder="${t.mealName}">
        <input type="time" value="${m.time}" onchange="nb.meals[${i}].time=this.value" style="background:#0d1319;border:1px solid var(--line-d);border-radius:10px;padding:8px;color:#fff">
        <button class="btn btn-d btn-s" onclick="nb.meals.splice(${i},1);renderNutriBuilder()">✕</button>
      </div>
      ${m.items.map((it,j)=>`<div style="display:grid;grid-template-columns:1fr 80px 30px;gap:8px;margin-bottom:8px">
        ${comboHTML('fd'+i+'_'+j, t.typeExFood, it.food||'')}
        <input type="number" value="${it.g}" onchange="nb.meals[${i}].items[${j}].g=+this.value;renderNutriBuilder()" placeholder="g" style="background:#0d1319;border:1px solid var(--line-d);border-radius:10px;padding:8px;color:#fff">
        <button class="btn btn-d btn-s" style="padding:6px" onclick="nb.meals[${i}].items.splice(${j},1);renderNutriBuilder()">✕</button>
      </div>`).join('')}
      <button class="btn btn-g btn-s" onclick="nb.meals[${i}].items.push({food:'',g:100});renderNutriBuilder()">＋ ${t.addFood}</button>
    </div>`).join('')}
  <div style="display:flex;gap:10px;flex-wrap:wrap">
    <button class="btn btn-g" onclick="nb.meals.push({id:uid(),name:{en:'Meal',ar:'وجبة'},time:'12:00',done:false,items:[{food:'',g:100}]});renderNutriBuilder()">＋ ${t.addMeal}</button>
    <button class="btn btn-p" style="flex:1" onclick="saveNutri()">${t.assignPlan}</button>
    <button class="btn btn-g" onclick="closeModal()">${t.cancel}</button>
  </div>`);
  nb.meals.forEach((m,i)=>m.items.forEach((it,j)=>{
    const id='fd'+i+'_'+j;
    makeCombo(id, FOOD_DB.map(f=>({v:f.n, d:f.n, s:f.cat+' · '+f.kcal+' kcal/100g'})),
      v=>{ nb.meals[i].items[j].food=v; });
    if(it.food) window['CB_'+id].picked=it.food;
  }));
}
function calcTargets(cid){
  const t=L(); const c=DB.users.find(u=>u.id===cid); const recs=DB.records.filter(r=>r.clientId===cid).sort((a,b)=>b.date.localeCompare(a.date));
  const w=recs[0]?.w||75, h=c?.height||175, a=c?.age||25, g=c?.gender||'male';
  openModal(`<h3>⚡ ${t.calcTitle}</h3>
  <label class="fld"><span>${t.activity}</span><select id="ctAct">
    <option value="1.2">${t.act1}</option><option value="1.375" selected>${t.act2}</option><option value="1.55">${t.act3}</option><option value="1.725">${t.act4}</option>
  </select></label>
  <label class="fld"><span>${t.goal}</span><select id="ctGoal">
    <option value="cut">${t.fatloss}</option><option value="bulk" selected>${t.muscle}</option><option value="keep">${t.recomp}</option>
  </select></label>
  <div style="color:#69758A;font-size:11.5px;margin-bottom:12px">${t.bmrNote} · ${w}kg / ${h}cm / ${a}</div>
  <div style="display:flex;gap:10px"><button class="btn btn-p" style="flex:1" onclick="
    const bmr=(10*${w})+(6.25*${h})-(5*${a})+(${g==='male'?5:-161});
    let k=bmr*+document.querySelector('#ctAct').value;
    const gl=document.querySelector('#ctGoal').value;
    if(gl==='cut')k-=400; if(gl==='bulk')k+=300;
    nb.targets={kcal:Math.round(k),p:Math.round(${w}*(gl==='cut'?2.2:1.8)),f:Math.round(k*0.25/9),c:Math.round((k-${w}*(gl==='cut'?2.2:1.8)*4-k*0.25)/4)};
    renderNutriBuilder();">${t.calc}</button>
  <button class="btn btn-g" onclick="renderNutriBuilder()">${t.cancel}</button></div>`);
}
function saveNutri(){
  nb.meals.forEach((m,i)=>m.items.forEach((it,j)=>{
    const c=window['CB_fd'+i+'_'+j];
    if(c&&c.picked) it.food=c.picked;
  }));
  nb.meals=nb.meals.filter(m=>m.items.some(i=>i.food));
  nb.meals.forEach(m=>m.items=m.items.filter(i=>i.food));
  const cur=DB.nutri.find(n=>n.clientId===nb.cid);
  if(cur){ cur.targets=nb.targets; cur.meals=nb.meals; }
  else DB.nutri.push({id:uid(),clientId:nb.cid,createdAt:today(),targets:nb.targets,meals:nb.meals,createdBy:APP.user.id});
  feedAdd(nb.cid,'🥗',(APP.lang==='ar'?'الكوتش حدث خطة التغذية':'Coach updated the nutrition plan'));
  notify(nb.cid,'plan',L().nNutriAssigned,L().nutriPlan);
  saveDB(); closeModal(); toast(L().planAssigned); renderApp();
}

