/* ---------- CLIENT: Dashboard ---------- */
function vClientDash(){
  const t=L(), u=APP.user, hr=new Date().getHours();
  const plan=DB.plans.find(p=>p.clientId===u.id), np=DB.nutri.find(n=>n.clientId===u.id);
  const recs=DB.records.filter(r=>r.clientId===u.id).sort((a,b)=>a.date.localeCompare(b.date));
  const last=recs[recs.length-1], first=recs[0];
  const dayIdx=(new Date().getDay()+6)%7;
  const todayW=plan&&plan.days.length?plan.days[dayIdx%plan.days.length]:null;
  const doneMeals=np?np.meals.filter(m=>m.done).length:0;
  const adh=np?Math.round(doneMeals/np.meals.length*100):0;
  return topbar(`${hr<12?t.goodMorning:t.goodEvening}, ${esc(u.name.split(' ')[0])} 👋`,t.heroSub)+`
  <div class="hero-card" style="margin-bottom:16px"><div class="glow"></div>
    <div class="gh">${t==I18N.en?'TRAIN · EAT · PROGRESS':'تدرب · كل · تقدم'}</div>
    <div class="gs">${t.heroSub}</div>
    <a class="btn btn-p" style="margin-top:16px" href="#/client/training">${t.viewPlan}</a>
  </div>
  <div class="grid g4" style="margin-bottom:16px">
    <a href="#/client/training" class="card stat" style="text-decoration:none"><div class="ic">${IC.dumb}</div><div class="l">${t.todayWorkout}</div>
      <div class="v" style="font-size:15px">${todayW?TD(APP.lang==='ar'?todayW.name.ar:todayW.name.en):t.restDay}</div></a>
    <a href="#/client/nutrition" class="card stat" style="text-decoration:none"><div class="ic">${IC.meal}</div><div class="l">${t.todayNutri}</div>
      <div class="v" style="font-size:15px">${np?`${doneMeals}/${np.meals.length} ${t.meal}`:t.noNutri}</div></a>
    <a href="#/client/progress" class="card stat" style="text-decoration:none"><div class="ic">${IC.chart}</div><div class="l">${t.weight}</div>
      <div class="v" style="font-size:20px">${last?last.w+' kg':'—'}</div>
      <div class="d ${first&&last&&last.w<first.w?'up':''}">${first&&last?(last.w-first.w).toFixed(1)+' kg':''}</div></a>
    <div class="card stat" style="align-items:center;flex-direction:row;gap:12px">${ringSVG(adh)}<div><div class="l">${t.weeklyAdh}</div><div class="d up">${doneMeals}/${np?np.meals.length:0} ✓</div></div></div>
  </div>
  <div class="grid g2">
    <div class="card"><h3>${t.todayWorkout}</h3>
      ${todayW?dayCardHTML(todayW,dayIdx%plan.days.length,u.id,true):`<div class="empty">😴 ${t.restDay}</div>`}</div>
    <div class="card"><h3>${t.yourCoach}</h3>${chatHTML('admin1')}</div>
  </div>`;
}
function toggleDayDone(i){
  const plan=DB.plans.find(p=>p.clientId===APP.user.id); if(!plan) return;
  plan.days[i]._done=!plan.days[i]._done;
  const dn=APP.lang==='ar'?plan.days[i].name.ar:plan.days[i].name.en;
  feedAdd(APP.user.id,'🏋️',(APP.lang==='ar'?(plan.days[i]._done?'أنهى تمرين: ':'ألغى إنهاء تمرين: ')+dn:(plan.days[i]._done?'Completed workout: ':'Unchecked workout: ')+(plan.days[i].name.en)));
  if(plan.days[i]._done) notify('admin1','workout',APP.user.name,L().nCompletedWorkout+': '+plan.days[i].name.en);
  saveDB(); toast(L().workoutDone); renderApp();
}
function toggleMeal(mid){
  const np=DB.nutri.find(n=>n.clientId===APP.user.id); if(!np) return;
  const m=np.meals.find(x=>x.id===mid); m.done=!m.done;
  feedAdd(APP.user.id,'🥗',(APP.lang==='ar'?(m.done?'أنهى وجبة: ':'ألغى إنهاء وجبة: ')+m.name.ar:(m.done?'Completed meal: ':'Unchecked meal: ')+m.name.en));
  if(m.done) notify('admin1','meal',APP.user.name,L().nCompletedMeal+': '+m.name.en);
  saveDB(); toast(L().mealDone); renderApp();
}

/* ---------- CLIENT: Training / Nutrition / Progress / Messages ---------- */
function vTraining(){
  const t=L(), u=APP.user, plan=DB.plans.find(p=>p.clientId===u.id);
  return topbar(t.training,plan?`${plan.days.length} ${t.day} · ${plan.createdAt}`:'')+
    (plan?plan.days.map((d,i)=>dayCardHTML(d,i,u.id,true)).join(''):`<div class="card"><div class="empty"><div class="ei">🏋️</div>${t.noPlan}</div></div>`);
}
function vNutrition(){
  const t=L(), u=APP.user, np=DB.nutri.find(n=>n.clientId===u.id);
  return topbar(t.nutrition,t.fromFood)+
    (np?nutriPlanHTML(np,u.id,true):`<div class="card"><div class="empty"><div class="ei">🥗</div>${t.noNutri}</div></div>`);
}
function vProgress(){
  const t=L(), u=APP.user;
  const recs=DB.records.filter(r=>r.clientId===u.id).sort((a,b)=>a.date.localeCompare(b.date));
  const last=recs[recs.length-1], first=recs[0];
  if(recs.length>1) onCharts(()=>lineChart($('#chW'),recs.map(r=>r.date.slice(5)),recs.map(r=>r.w),'#2FD4F5'));
  return topbar(t.progress)+`
  <div class="grid g3" style="margin-bottom:16px">
    <div class="card stat"><div class="l">${t.current}</div><div class="v">${last?last.w:'—'} kg</div></div>
    <div class="card stat"><div class="l">${t.change}</div><div class="v ${first&&last&&last.w<first.w?'up':''}">${first&&last?(last.w-first.w).toFixed(1):'—'} kg</div></div>
    <div class="card stat"><div class="l">${t.bodyFat}</div><div class="v">${last&&last.bf?last.bf+'%':'—'}</div></div>
  </div>
  <div class="card" style="margin-bottom:14px"><h3>${t.weightLog}</h3>${recs.length>1?'<canvas class="chart" id="chW"></canvas>':''}
    <div class="tbl-wrap" style="margin-top:12px"><table class="tbl" style="min-width:0"><thead><tr><th>${t.date}</th><th>${t.weight}</th><th>${t.bodyFat}</th></tr></thead>
    <tbody>${recs.slice().reverse().map(r=>`<tr><td>${r.date}</td><td><b>${r.w} kg</b></td><td>${r.bf?r.bf+'%':'—'}</td></tr>`).join('')}</tbody></table></div>
    <button class="btn btn-p btn-s" style="margin-top:14px" onclick="addRecord('${u.id}')">＋ ${t.addRecord}</button></div>`;
}
function vClientMessages(){
  const t=L();
  return topbar(t.messages)+`<div class="card"><h3>${t.yourCoach}</h3>${chatHTML('admin1')}</div>`;
}

/* ---------- Keep focus while live-searching ---------- */
function refocus(id){ const n=document.getElementById(id); if(n){ n.focus(); const l=n.value.length; try{ n.setSelectionRange(l,l); }catch(e){} } }

/* ---------- Library: add custom exercise / food ---------- */
function openLibAdd(){
  const t=L(), ar=APP.lang==='ar';
  if(libTab===0){
    openModal(`<h3>${ar?'إضافة تمرين جديد':'Add New Exercise'}</h3>
    <label class="fld"><span>${ar?'الاسم بالعربي':'Arabic name'}</span><input id="laN"></label>
    <label class="fld"><span>${ar?'الاسم بالإنجليزي':'English name'}</span><input id="laE" dir="ltr"></label>
    <label class="fld"><span>${t.category}</span><select id="laC">${EX_CATS.map(c=>`<option value="${c}">${t[c]}</option>`).join('')}</select></label>
    <div class="row2"><label class="fld"><span>${t.muscle}</span><input id="laM"></label>
    <label class="fld"><span>${t.equipment}</span><input id="laQ"></label></div>
    <div style="display:flex;gap:10px"><button class="btn btn-p" style="flex:1" onclick="saveLibAdd(0)">${t.save}</button>
    <button class="btn btn-g" onclick="closeModal()">${t.cancel}</button></div>`);
  } else {
    openModal(`<h3>${ar?'إضافة صنف جديد':'Add New Food'}</h3>
    <label class="fld"><span>${ar?'اسم الصنف':'Food name'}</span><input id="lfN"></label>
    <label class="fld"><span>${t.category}</span><input id="lfC" list="foodCats"><datalist id="foodCats">${[...new Set(FOOD_DB.map(f=>f.cat))].map(c=>`<option value="${esc(c)}">`).join('')}</datalist></label>
    <div class="row2"><label class="fld"><span>${t.kcal100}</span><input id="lfK" type="number" step="0.1"></label>
    <label class="fld"><span>${t.protein} (g)</span><input id="lfP" type="number" step="0.1"></label></div>
    <div class="row2"><label class="fld"><span>${t.carbs} (g)</span><input id="lfCb" type="number" step="0.1"></label>
    <label class="fld"><span>${t.fats} (g)</span><input id="lfF" type="number" step="0.1"></label></div>
    <label class="fld"><span>${t.fiber} (g)</span><input id="lfFb" type="number" step="0.1"></label>
    <div style="display:flex;gap:10px"><button class="btn btn-p" style="flex:1" onclick="saveLibAdd(1)">${t.save}</button>
    <button class="btn btn-g" onclick="closeModal()">${t.cancel}</button></div>`);
  }
}
function saveLibAdd(kind){
  if(kind===0){
    const n=$('#laN').value.trim(); if(!n){ toast('!'); return; }
    const e={n, e:$('#laE').value.trim()||n, c:$('#laC').value, m:$('#laM').value.trim()||'—', eq:$('#laQ').value.trim()||'—'};
    EX_DB.push(e);
    try{ const a=JSON.parse(localStorage.getItem('oc_custom_ex')||'[]'); a.push(e); localStorage.setItem('oc_custom_ex',JSON.stringify(a)); }catch(_){}
  } else {
    const n=$('#lfN').value.trim(); if(!n){ toast('!'); return; }
    const f={n, cat:$('#lfC').value.trim()||'أخرى', kcal:+$('#lfK').value||0, p:+$('#lfP').value||0, c:+$('#lfCb').value||0, f:+$('#lfF').value||0, fib:+$('#lfFb').value||0};
    FOOD_DB.push(f);
    try{ const a=JSON.parse(localStorage.getItem('oc_custom_foods')||'[]'); a.push(f); localStorage.setItem('oc_custom_foods',JSON.stringify(a)); }catch(_){}
  }
  closeModal(); toast(L().saved); renderApp();
}

/* ---------- Boot ---------- */
document.addEventListener('DOMContentLoaded',()=>{
  try{ EX_DB.push.apply(EX_DB,JSON.parse(localStorage.getItem('oc_custom_ex')||'[]')); FOOD_DB.push.apply(FOOD_DB,JSON.parse(localStorage.getItem('oc_custom_foods')||'[]')); }catch(e){}
  const hp=$('#page-home'); if(hp){ hp.lang=APP.lang; hp.dir=APP.lang==='ar'?'rtl':'ltr'; }
  try{ window.__applyHomeLang && window.__applyHomeLang(APP.lang); }catch(e){}
  setLang(APP.lang); route();
});
window.addEventListener('load',route);